"""Pure ORD_LINE renumbering for Meridian CRM migration RIN-02."""

from decimal import Decimal


def _order_id(row: dict) -> str:
    """Return ORD_ID using the legacy missing-key empty-string convention."""
    value = row.get("ORD_ID", "")
    return value if isinstance(value, str) else str(value)


def _line_number(row: dict) -> Decimal:
    """Return LINE_NO as a numeric value; missing or empty values coerce to zero."""
    value = row.get("LINE_NO", "")
    if value == "":
        return Decimal(0)
    return Decimal(str(value))


def renumber(lines: list[dict]) -> list[dict]:
    """Remove soft-deleted lines and renumber surviving lines per order."""
    surviving = [
        (index, dict(row))
        for index, row in enumerate(lines)
        if row.get("DEL_FLG", "") != "Y"
    ]

    surviving.sort(
        key=lambda item: (
            _order_id(item[1]),
            _line_number(item[1]),
            item[0],
        )
    )

    result: list[dict] = []
    current_order: str | None = None
    new_line_number = 0

    for _, row in surviving:
        order_id = _order_id(row)
        if order_id != current_order:
            current_order = order_id
            new_line_number = 1
        else:
            new_line_number += 1

        row["LINE_NO"] = new_line_number
        result.append(row)

    return result
